`,a.jsxs(e.ul,{children:[`
`,a.jsxs(e.li,{children:["Decoding is bound by memory. At ",s(A.longest)," cached positions multi-head attention reads its cache at ",r(A.mhaBandwidthShare)," of the peak bandwidth and takes ",h(A.mhaLatency)," per step and layer."]}),`
`,a.jsxs(e.li,{children:["Four KV heads store a quarter of multi-head attention's ",s(W.mha)," elements, and the step takes ",l(A.mhaOverGqa,1)," times less time."]}),`
`,a.jsxs(e.li,{children:["Latent attention stores ",s(W.dC)," + ",s(W.dR)," = ",s(W.mla)," elements, ",r(W.mlaAgainstGqa)," of grouped-query attention's ",s(W.gqa),". Absorbed, it runs within ",r(A.absorbedOverGqa-1)," of grouped-query attention, although two plain matrix multiplications read the latent twice, ",s(A.absorbedReadPerToken)," elements per token. A fused kernel would read it once."]}),`
`,a.jsxs(e.li,{children:["Unabsorbed, the step takes ",h(A.unabsorbedLatency),", ",l(A.unabsorbedOverAbsorbed,0)," times the absorbed step. Absorption is what makes the small cache fast to read."]}),`
